{
  "client": {"name": "Acme Analytics Ltd", "contact_email": "dana@acme.example", "contract_notice_days": 30, "renewal_date": "2026-12-31"},
  "inputs_used": [
    {"name": "retainer-msa-2025", "source": "contracts/acme/msa-2025.pdf#clause-9.3"},
    {"name": "engagement-log-q1-q2", "source": "engagements/acme/2026-log.md"},
    {"name": "revenue-t12m", "source": "finance/revenue-2025-07-to-2026-06.xlsx"}
  ],
  "rate": {"currency": "EUR", "unit": "per_month_retainer", "current": 6000, "new": 6720, "change_pct": 12, "is_range_or_open": false},
  "schedule": {"letter_date": "2026-07-01", "effective_date": "2026-09-01", "days_to_effective": 62, "billing_cycles_to_effective": 2, "raises_in_last_12_months": 0},
  "justification": {
    "value_deltas": [
      {"kind": "capability_depended_on", "statement": "Since March 2026 I own the release pipeline Acme previously paid an agency EUR 2,400 per month for", "input_name": "engagement-log-q1-q2"},
      {"kind": "metric_moved", "statement": "Deploy lead time fell from 9 days to 1 day between March and June 2026", "input_name": "engagement-log-q1-q2"}
    ],
    "cpi_or_costs_mentioned": false,
    "cpi_or_costs_is_sole_justification": false
  },
  "inflight_work": [
    {"reference": "SOW-2026-03 data-warehouse migration", "kind": "signed_sow", "completes_at_current_rate": true},
    {"reference": "Retainer period July-August 2026 (prepaid)", "kind": "prepaid_retainer_period", "completes_at_current_rate": true}
  ],
  "letter": {"word_count": 196, "opens_with_value_delivered": true, "states_protected_work": true, "closes_with_effective_and_follow_up_dates": true, "banned_phrases_found": [], "personal_cost_narrative": false, "concession_in_letter": false},
  "prepared_concession": {"description": "Current rate held until 2026-12-31 against a prepaid six-month retainer invoiced in September", "use_only_in_follow_up": true},
  "churn_risk": {
    "class": "negotiate",
    "revenue_share_pct_t12m": 18,
    "alternatives": "Could re-engage the agency at roughly 2x my retainer, or hire a platform engineer with a 3-month lead",
    "recent_feedback": "Q2 review: 'the pipeline work changed how we ship'; NPS 9",
    "payment_behaviour": "Every retainer invoice paid within net 15 across 14 months"
  },
  "follow_up": {
    "date": "2026-07-08",
    "days_after_letter": 7,
    "path_if_confirmed": "Send the updated retainer schedule (clause 9.3 variation) for e-signature",
    "path_if_no_reply": "Two-line reminder restating the 2026-09-01 effective date and asking for written confirmation",
    "path_if_push_back": "Offer the prepared concession once; if declined, propose a 30-minute scope call"
  },
  "acknowledgement": {"received_in_writing": true, "received_on": "2026-07-06", "response_state": "confirmed", "new_rate_applied": false}
}

